// 초록 약병 (연성술사 조수 A): 둥근 병 · 코르크
PXU_WPN.gflask = (F, d) => { const [hx, hy] = pxsMHand(F), [dx, dy] = pxsDir(F.a || 0), px = -dy, py = dx, out = [], k = (d && d.ms) || 1, L = 0.5 * k, o = L - 0.5;
  const at = (t, s, ch) => out.push([hx + 0.5 + dx * t + px * s, hy + 0.5 + dy * t + py * s, ch]);
  for (let t = -0.5; t <= L; t += 0.5) at(t, 0, t < -0.5 + 0.6 ? 'g' : 'S');
  for (const [t, s, ch] of [[5.0,0.0,'O'],[4.0,0.0,'g'],[3.0,-1.0,'g'],[3.0,0.0,'L'],[3.0,1.0,'g'],[2.0,-1.0,'L'],[2.0,0.0,'L'],[2.0,1.0,'L'],[1.0,0.0,'L']]) for (const e of [-0.25, 0.25]) for (const f of [-0.25, 0.25]) at(t + o + e, s + f, ch);
  return out; };
PXU_FXW.gflask = 'staff';
// 보라 약병 (연성술사 조수 B)
PXU_WPN.pflask = (F, d) => { const [hx, hy] = pxsMHand(F), [dx, dy] = pxsDir(F.a || 0), px = -dy, py = dx, out = [], k = (d && d.ms) || 1, L = 0.5 * k, o = L - 0.5;
  const at = (t, s, ch) => out.push([hx + 0.5 + dx * t + px * s, hy + 0.5 + dy * t + py * s, ch]);
  for (let t = -0.5; t <= L; t += 0.5) at(t, 0, t < -0.5 + 0.6 ? 'g' : 'S');
  for (const [t, s, ch] of [[5.0,0.0,'O'],[4.0,0.0,'g'],[3.0,-1.0,'g'],[3.0,0.0,'V'],[3.0,1.0,'g'],[2.0,-1.0,'V'],[2.0,0.0,'V'],[2.0,1.0,'V'],[1.0,0.0,'V']]) for (const e of [-0.25, 0.25]) for (const f of [-0.25, 0.25]) at(t + o + e, s + f, ch);
  return out; };
PXU_FXW.pflask = 'staff';
